// The C# write path must not destroy a hand edit.
//
// The marker-only guard refused a file whose <auto-generated/> marker was ABSENT and
// overwrote everything else — but a hand-edited generated file still carries its
// marker, so the one case worth protecting was the one case that got clobbered. It was
// also wrong the other way: a file this generator wrote whose template later stopped
// emitting the marker was refused as though it were somebody's source.
//
// The decision now comes from a hash manifest recording what we wrote, mirroring
// codegen-ts:
//
//     identical fresh content              -> "unchanged"
//     file still hashes to what we wrote    -> "written"   (nothing is lost)
//     hash mismatch, or no record at all    -> "refused"   (fail closed)
//
// With no GenStateDir there is no record, so the legacy marker rule stands — mirroring
// TS, where a runGen with no projectRoot also gets weaker guarantees.

using System.Text.Json;
using MetaObjects.Codegen;
using MetaObjects.Loader;
using MetaObjects.Meta;
using Xunit;

namespace MetaObjects.Codegen.Tests;

public class OverwriteHashManifestTests : IDisposable
{
    private readonly string _root = Path.Combine(
        Path.GetTempPath(), "mo-hash-" + Guid.NewGuid().ToString("N"));

    private string OutDir => Path.Combine(_root, "generated");
    private string StateDir => Path.Combine(_root, ".metaobjects", ".gen-state");
    private string TargetPath => Path.Combine(OutDir, "A.cs");

    public void Dispose()
    {
        if (Directory.Exists(_root)) Directory.Delete(_root, recursive: true);
    }

    /// <summary>A generator emitting one fixed file, so the test is about the write
    /// policy rather than about any real generator's output.</summary>
    private sealed class FixedGenerator : IGenerator
    {
        private readonly string _content;
        public FixedGenerator(string content) => _content = content;
        public string Name => "fixed";
        public IEnumerable<EmittedFile> Generate(GenContext ctx) =>
            new[] { new EmittedFile("A.cs", _content) };
    }

    private CodegenRunner.RunResult Run(string content, bool withState = true)
    {
        var config = new GenConfig
        {
            OutDir = OutDir,
            Namespace = "Probe",
            GenStateDir = withState ? StateDir : null,
        };
        return CodegenRunner.Run(config, Load(), new IGenerator[] { new FixedGenerator(content) });
    }

    private const string Model = """
    { "metadata.root": { "package": "probe", "children": [
      { "object.value": { "name": "Shape", "children": [
        { "field.string": { "name": "label" } }
      ]}}
    ]}}
    """;

    private static MetaRoot Load()
    {
        var r = new MetaDataLoader().Load([new InMemoryStringSource(Model, id: "probe.json")]);
        Assert.Empty(r.Errors);
        return r.Root;
    }

    [Fact]
    public void HandEditedFile_IsRefused_AndSurvives()
    {
        var original = "// <auto-generated/>\nclass A { }\n";
        // "written" covers create AND overwrite in this port's vocabulary.
        Assert.Equal("written", Run(original).Files[0].Status);

        var edited = original + "// my hand edit\n";
        File.WriteAllText(TargetPath, edited);

        var result = Run("// <auto-generated/>\nclass A { int X; }\n");
        Assert.Equal("refused", result.Files[0].Status);
        Assert.Equal(edited, File.ReadAllText(TargetPath));
        Assert.Contains(result.Warnings, w => w.Contains("A.cs"));
    }

    [Fact]
    public void UntouchedFile_IsOverwritten()
    {
        Run("// <auto-generated/>\nclass A { }\n");
        var fresh = "// <auto-generated/>\nclass A { int X; }\n";

        var result = Run(fresh);
        Assert.Equal("written", result.Files[0].Status);
        Assert.Equal(fresh, File.ReadAllText(TargetPath));
    }

    [Fact]
    public void IdenticalContent_IsUnchanged()
    {
        var content = "// <auto-generated/>\nclass A { }\n";
        Run(content);
        Assert.Equal("unchanged", Run(content).Files[0].Status);
    }

    [Fact]
    public void FileWithNoRecord_IsRefused_NotAdopted()
    {
        // Fail closed: adopting the content would launder the edit into the manifest
        // and license the next run to overwrite it.
        Directory.CreateDirectory(OutDir);
        File.WriteAllText(TargetPath, "// <auto-generated/>\nsomeone else wrote this\n");

        var result = Run("// <auto-generated/>\nclass A { }\n");
        Assert.Equal("refused", result.Files[0].Status);
        Assert.Contains("someone else wrote this", File.ReadAllText(TargetPath));
    }

    [Fact]
    public void MarkerIsNoLongerConsulted_OurOwnFileIsOurs()
    {
        // No marker at all. Under the old rule this refused, which was wrong: the file
        // is this generator's own output.
        Run("class A { }\n");
        Assert.Equal("written", Run("class A { int X; }\n").Files[0].Status);
    }

    [Fact]
    public void Manifest_IsSorted_BecauseItIsCommitted()
    {
        var config = new GenConfig { OutDir = OutDir, Namespace = "Probe", GenStateDir = StateDir };
        var gens = new IGenerator[]
        {
            new MultiGenerator(new[] { "z.cs", "a.cs", "m.cs" }),
        };
        CodegenRunner.Run(config, Load(), gens);

        var json = File.ReadAllText(Path.Combine(StateDir, ".hashes.json"));
        var keys = JsonSerializer.Deserialize<Dictionary<string, string>>(json)!.Keys.ToList();
        // Insertion order would make a committed diff depend on generation order.
        Assert.Equal(new[] { "a.cs", "m.cs", "z.cs" }, keys.ToArray());
    }

    private sealed class MultiGenerator : IGenerator
    {
        private readonly string[] _paths;
        public MultiGenerator(string[] paths) => _paths = paths;
        public string Name => "multi";
        public IEnumerable<EmittedFile> Generate(GenContext ctx) =>
            _paths.Select(p => new EmittedFile(p, $"// {p}\n"));
    }

    [Fact]
    public void NoManifest_ManyRefusals_ProduceOneAggregatedMessage()
    {
        // The upgrade path. Every refusal shares one cause and one fix, so a wall of
        // per-file warnings would bury the instruction.
        Directory.CreateDirectory(OutDir);
        foreach (var name in new[] { "a.cs", "m.cs", "z.cs" })
            File.WriteAllText(Path.Combine(OutDir, name), "// stale from an older engine\n");

        var config = new GenConfig { OutDir = OutDir, Namespace = "Probe", GenStateDir = StateDir };
        var result = CodegenRunner.Run(
            config, Load(), new IGenerator[] { new MultiGenerator(new[] { "a.cs", "m.cs", "z.cs" }) });

        Assert.Equal(3, result.Files.Count(f => f.Status == "refused"));
        Assert.Single(result.Warnings);
        Assert.Contains("3 existing file(s)", result.Warnings[0]);
        Assert.Contains(".hashes.json", result.Warnings[0]);
    }

    [Fact]
    public void WithoutGenStateDir_LegacyMarkerRuleStands()
    {
        // Back-compat for programmatic callers, mirroring TS's no-projectRoot fallback.
        Directory.CreateDirectory(OutDir);
        File.WriteAllText(TargetPath, "// hand written, no marker\n");
        Assert.Equal("skipped-handwritten", Run("fresh\n", withState: false).Files[0].Status);

        File.WriteAllText(TargetPath, "// <auto-generated/>\nold\n");
        Assert.Equal("written", Run("// <auto-generated/>\nnew\n", withState: false).Files[0].Status);
    }
}
